pm.environment.set(
    "randomUserName",
    "teste_" + pm.variables.replaceIn("{{$guid}}")
);

// Senha de exemplo exclusiva para esta API de testes.
pm.environment.set("password", "Teste@123Aa");

const schema = {
    type: "object",
    required: ["userID", "username", "books"],
    properties: {
        userID: { type: "string", minLength: 1 },
        username: { type: "string", minLength: 1 },
        books: {
            type: "array",
            items: { type: "object" }
        }
    }
};

pm.variables.set("createUserSchema", JSON.stringify(schema));

const schema = JSON.parse(pm.variables.get("createUserSchema"));
const userName = pm.variables.replaceIn("{{$randomUserName}}");
const password = "Teste@123Aa"; // Senha de exemplo para esta API de testes.

pm.environment.set("randomUserName", userName);
pm.environment.set("password", password);

if (pm.response.code !== 201) {
    console.log("Erro na criação:", pm.response.text());
}


pm.test(
    "Dado um usuário válido, quando solicito sua criação, então recebo status 201",
    function () {
        pm.response.to.have.status(201);
    }
);

pm.test(
    "Dado um usuário criado, quando verifico a resposta, então ela atende ao contrato JSON",
    function () {
        pm.response.to.be.json;
        pm.response.to.have.jsonSchema(schema);
    }
);

pm.test(
    "Dado um usuário criado, quando verifico seu nome, então corresponde ao enviado",
    function () {
        pm.response.to.have.status(201);
        pm.response.to.have.jsonSchema(schema);

        const response = pm.response.json();
        const request = JSON.parse(
            pm.variables.replaceIn(pm.request.body.raw)
        );

        pm.expect(response.username).to.eql(request.userName);
    }
);

pm.test(
    "Dado que a criação foi validada, quando salvo os dados, então ficam disponíveis para as próximas requisições",
    function () {
        pm.response.to.have.status(201);
        pm.response.to.be.json;
        pm.response.to.have.jsonSchema(schema);

        const response = pm.response.json();
        const request = JSON.parse(
            pm.variables.replaceIn(pm.request.body.raw)
        );

        pm.expect(response.username).to.eql(request.userName);
        pm.expect(request.password).to.be.a("string").and.not.empty;

        pm.environment.set("userID", response.userID);
        pm.environment.set("userName", response.username);
        pm.environment.set("randomUserName", response.username);
        pm.environment.set("password", request.password);
    }
);

pm.environment.unset("token");

pm.test(
    "Dado um usuário cadastrado com credenciais válidas, quando solicito um token, então recebo um token válido e o salvo no ambiente",
    function () {
        pm.response.to.have.status(200);

        const response = pm.response.json();

        pm.expect(response.status, response.result).to.eql("Success");
        pm.expect(response.token).to.be.a("string").and.not.empty;
        pm.environment.set("token", response.token);
    }
);

pm.test(
    "Dado um usuário cadastrado, quando verifico sua autorização, então recebo status 200",
    function () {
        pm.response.to.have.status(200);
    }
);

pm.test(
    "Dado uma consulta de autorização, quando verifico o contrato da resposta, então recebo um booleano em JSON",
    function () {
        pm.response.to.be.json;
        pm.response.to.have.jsonSchema({
            type: "boolean"
        });
    }
);

pm.test(
    "Dado um usuário autorizado, quando consulto sua autorização, então a resposta é true",
    function () {
        pm.expect(pm.response.json()).to.eql(true);
    }
);

pm.test(
    "Dado um usuário existente e um token válido, quando consulto seu perfil, então recebo status 200",
    function () {
        pm.response.to.have.status(200);
    }
);

pm.test(
    "Dado uma consulta de perfil, quando verifico a resposta, então ela atende ao contrato do usuário",
    function () {
        pm.response.to.be.json;
        pm.response.to.have.jsonSchema({
            type: "object",
            required: ["userId", "username", "books"],
            properties: {
                userId: { type: "string", minLength: 1 },
                username: { type: "string", minLength: 1 },
                books: {
                    type: "array",
                    items: { type: "object" }
                }
            }
        });
    }
);

pm.test(
    "Dado o usuário criado na F01, quando consulto seu perfil, então o ID e o nome correspondem aos dados salvos",
    function () {
        const response = pm.response.json();

        pm.expect(response.userId)
            .to.eql(pm.environment.get("userID"));

        pm.expect(response.username)
            .to.eql(pm.environment.get("randomUserName"));
    }
);

const schema = JSON.parse(pm.variables.get("booksSchema"));

pm.environment.unset("isbn1");
pm.environment.unset("isbn2");

pm.test(
    "Dado um catálogo disponível, quando consulto os livros, então recebo status 200",
    function () {
        pm.response.to.have.status(200);
    }
);

pm.test(
    "Dado uma consulta ao catálogo, quando verifico a resposta, então os livros atendem ao contrato JSON",
    function () {
        pm.response.to.be.json;
        pm.response.to.have.jsonSchema(schema);
    }
);

pm.test(
    "Dado um catálogo com pelo menos dois ISBNs distintos, quando sorteio dois livros, então salvo ISBNs diferentes para a próxima requisição",
    function () {
        pm.response.to.have.status(200);
        pm.response.to.be.json;
        pm.response.to.have.jsonSchema(schema);

        const books = pm.response.json().books;
        const isbns = [...new Set(books.map(book => book.isbn))];

        pm.expect(
            isbns.length,
            "É necessário ter pelo menos dois ISBNs distintos"
        ).to.be.at.least(2);

        const index1 = Math.floor(Math.random() * isbns.length);
        const isbn1 = isbns.splice(index1, 1)[0];

        const index2 = Math.floor(Math.random() * isbns.length);
        const isbn2 = isbns[index2];

        pm.expect(isbn1).to.not.eql(isbn2);

        pm.environment.set("isbn1", isbn1);
        pm.environment.set("isbn2", isbn2);
    }
);

const schema = {
    type: "object",
    required: ["books"],
    properties: {
        books: {
            type: "array",
            minItems: 2,
            items: {
                type: "object",
                required: [
                    "isbn", "title", "subTitle", "author",
                    "publish_date", "publisher", "pages",
                    "description", "website"
                ],
                properties: {
                    isbn: { type: "string", pattern: "^[0-9]{13}$" },
                    title: { type: "string", minLength: 1 },
                    subTitle: { type: "string" },
                    author: { type: "string", minLength: 1 },
                    publish_date: {
                        type: "string",
                        format: "date-time"
                    },
                    publisher: { type: "string", minLength: 1 },
                    pages: { type: "integer", minimum: 1 },
                    description: { type: "string" },
                    website: { type: "string", format: "uri" }
                }
            }
        }
    }
};

pm.variables.set("booksSchema", JSON.stringify(schema));

const schema = {
    type: "object",
    required: ["books"],
    properties: {
        books: {
            type: "array",
            minItems: 2,
            maxItems: 2,
            items: {
                type: "object",
                required: ["isbn"],
                properties: {
                    isbn: {
                        type: "string",
                        pattern: "^[0-9]{13}$"
                    }
                }
            }
        }
    }
};

pm.variables.set("rentBooksSchema", JSON.stringify(schema));

const schema = JSON.parse(pm.variables.get("rentBooksSchema"));

pm.test(
    "Dado um usuário autorizado e dois livros disponíveis, quando adiciono os livros à sua coleção, então recebo status 201",
    function () {
        pm.response.to.have.status(201);
    }
);

pm.test(
    "Dado uma inclusão de dois livros, quando verifico a resposta, então ela atende ao contrato JSON",
    function () {
        pm.response.to.be.json;
        pm.response.to.have.jsonSchema(schema);
    }
);

pm.test(
    "Dado dois ISBNs escolhidos, quando adiciono os livros, então a resposta contém exatamente esses dois ISBNs",
    function () {
        pm.response.to.have.status(201);
        pm.response.to.have.jsonSchema(schema);

        const request = JSON.parse(
            pm.variables.replaceIn(pm.request.body.raw)
        );

        const esperados = request.collectionOfIsbns.map(
            book => book.isbn
        );

        pm.expect(esperados).to.have.lengthOf(2);
        pm.expect(esperados[0]).to.not.eql(esperados[1]);

        const recebidos = pm.response.json().books.map(
            book => book.isbn
        );

        pm.expect(recebidos).to.have.lengthOf(2);
        pm.expect(recebidos).to.have.members(esperados);
    }
);

const schema = JSON.parse(pm.variables.get("userBooksSchema"));

pm.test(
    "Dado um usuário existente e um token válido, quando consulto seu perfil, então recebo status 200",
    function () {
        pm.response.to.have.status(200);
    }
);

pm.test(
    "Dado o usuário criado anteriormente, quando consulto seu perfil, então o ID retornado corresponde ao ID salvo",
    function () {
        const response = pm.response.json();

        pm.expect(response.userId)
            .to.eql(pm.environment.get("userID"));
    }
);

pm.test(
    "Dado um usuário com os dois livros escolhidos, quando consulto seu perfil, então recebo exatamente esses dois livros",
    function () {
        const response = pm.response.json();

        const esperados = [
            pm.environment.get("isbn1"),
            pm.environment.get("isbn2")
        ];

        pm.expect(esperados[0]).to.be.a("string").and.not.empty;
        pm.expect(esperados[1]).to.be.a("string").and.not.empty;
        pm.expect(esperados[0]).to.not.eql(esperados[1]);

        pm.expect(response.books)
            .to.be.an("array").with.lengthOf(2);

        const recebidos = response.books.map(book => book.isbn);

        pm.expect(recebidos).to.have.members(esperados);
    }
);

